package app.relaydrop;
import android.content.*;
import android.database.Cursor;
import android.net.Uri;
import android.provider.DocumentsContract;
import org.json.*;
import java.io.IOException;
import java.util.*;

/** Directory names come only from a validated authorized server snapshot. */
final class DirectorySavePlan {
  static JSONArray create(JSONObject state,String selected)throws Exception{
    if(selected!=null&&!selected.isEmpty()&&!selected.matches("[a-fA-F0-9-]{36}"))throw new IOException("目录编号无效。");if(selected!=null&&selected.isEmpty())selected=null;ShareDirectorySupport.Snapshot tree=new ShareDirectorySupport.Snapshot(state);String prefix=tree.get(selected).path,rootName=selected==null?"共享文件池":tree.nodes.get(selected).getString("name");JSONArray out=new JSONArray();Map<String,String> jobs=new HashMap<>();Set<String> names=new HashSet<>();String rootId=UUID.randomUUID().toString();jobs.put(selected==null?"":selected,rootId);out.put(new JSONObject().put("id",rootId).put("kind","folder").put("name",rootName).put("relativePath",rootName).put("sourceFolderId",selected==null?JSONObject.NULL:selected).put("sourceFolderPath",prefix).put("parentJobId",JSONObject.NULL).put("size",0));
    ArrayList<ShareDirectorySupport.Folder> descendants=new ArrayList<>();for(ShareDirectorySupport.Folder f:tree.ordered)if(f.id!=null&&!Objects.equals(f.id,selected)&&(selected==null||f.path.startsWith(prefix+"/")))descendants.add(f);descendants.sort(Comparator.comparingInt(f->f.path.split("/").length));for(ShareDirectorySupport.Folder f:descendants){if(out.length()>=2000)throw new IOException("目录保存最多2,000个项目。");String parent=SharedFolders.nullable(tree.nodes.get(f.id),"parentId"),parentJob=jobs.get(parent==null?"":parent);if(parentJob==null)throw new IOException("目录层级发生变化。");String id=UUID.randomUUID().toString(),name=tree.nodes.get(f.id).getString("name");jobs.put(f.id,id);names.add(parentJob+"/"+name.toLowerCase(Locale.ROOT));out.put(new JSONObject().put("id",id).put("kind","folder").put("name",name).put("relativePath",rootName+"/"+(prefix.isEmpty()?f.path:f.path.substring(prefix.length()+1))).put("sourceFolderId",f.id).put("sourceFolderPath",f.path).put("parentJobId",parentJob).put("size",0));}
    JSONArray files=state.getJSONArray("files");int count=0;for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);if(!f.isNull("targetId")&&!f.optString("targetId").isEmpty())continue;String folder=SharedFolders.nullable(f,"folderId"),parentJob=jobs.get(folder==null?"":folder);if(parentJob==null)continue;if(++count>300||out.length()>=2000)throw new IOException("每批目录最多300个文件、2,000个项目，请选择子目录。");ReceiveQueueService.visibleFile(state,f.getString("id"));String base=PoolBackup.safeName(f.getString("name")),name=base;int dot=base.lastIndexOf('.');if(dot<=0)dot=base.length();for(int n=2;!names.add(parentJob+"/"+name.toLowerCase(Locale.ROOT));n++)name=base.substring(0,dot)+" ("+n+")"+base.substring(dot);String folderPath=tree.get(folder).path;String relative=rootName+"/"+(Objects.equals(folder,selected)?"":(prefix.isEmpty()?folderPath:folderPath.substring(prefix.length()+1))+"/")+name;PoolBackup.payloadPath("files/"+relative);out.put(new JSONObject().put("id",UUID.randomUUID().toString()).put("kind","file").put("fileId",f.getString("id")).put("name",f.getString("name")).put("outputName",name).put("relativePath",relative).put("folderId",folder==null?JSONObject.NULL:folder).put("parentJobId",parentJob).put("size",f.getLong("size")).put("sha256",f.getString("sha256")));}return out;
  }
  static Uri unique(Context context,Uri tree,Uri parent,String raw,boolean directory)throws Exception{String base=PoolBackup.safeName(raw);PoolBackup.payloadPath("files/"+base);Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,DocumentsContract.getDocumentId(parent));Set<String> names=new HashSet<>(),ids=new HashSet<>();try(Cursor c=context.getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null)){if(c==null)throw new IOException("无法读取保存目录。");while(c.moveToNext()){if(ids.size()>=50000)throw new IOException("保存目录项目过多。");ids.add(c.getString(0));names.add(c.getString(1).toLowerCase(Locale.ROOT));}}String candidate=base;int dot=directory?base.length():base.lastIndexOf('.');if(dot<=0)dot=base.length();for(int n=2;names.contains(candidate.toLowerCase(Locale.ROOT));n++)candidate=base.substring(0,dot)+" ("+n+")"+base.substring(dot);Uri output=DocumentsContract.createDocument(context.getContentResolver(),parent,directory?DocumentsContract.Document.MIME_TYPE_DIR:"application/octet-stream",candidate);if(output==null||ids.contains(DocumentsContract.getDocumentId(output)))throw new IOException("保存位置未新建独立项目，已停止以保护旧文件。");return output;}
}
